INTERVIEWER_PERMISSIONS = ["tests.view", "candidates.view", "results.view", "interviews.conduct"]


def create_default_roles(apps, schema_editor):
    """Create an "Interviewer" role and move members of the old Reviewers group onto it."""
    StaffRole = apps.get_model("assessments", "StaffRole")
    StaffProfile = apps.get_model("assessments", "StaffProfile")
    Group = apps.get_model("auth", "Group")
    role, _ = StaffRole.objects.get_or_create(
        name="Interviewer",
        defaults={
            "description": "Reviews attempts and conducts interviews. Cannot change tests or candidate access.",
            "permissions": INTERVIEWER_PERMISSIONS,
        },
    )
    group = Group.objects.filter(name="Reviewers").first()
    if group is None:
        return
    for user in group.user_set.filter(is_staff=False, is_superuser=False):
        StaffProfile.objects.get_or_create(user=user, defaults={"role": role})


